// textNode.js — dynamic width/height + {{ variable }} handle detection
import { useState, useRef, useEffect } from 'react';
import { Handle, Position } from 'reactflow';

const VARIABLE_REGEX = /\{\{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\}\}/g;

const MIN_W = 220;
const MIN_H = 80;

function extractVars(text) {
  const vars = [];
  const seen = new Set();
  let m;
  VARIABLE_REGEX.lastIndex = 0;
  while ((m = VARIABLE_REGEX.exec(text)) !== null) {
    if (!seen.has(m[1])) { seen.add(m[1]); vars.push(m[1]); }
  }
  return vars;
}

const accent = '#f59e0b';
const styles = {
  node: (w, h) => ({
    background: '#13161e',
    border: `1px solid ${accent}44`,
    borderRadius: '10px',
    minWidth: MIN_W,
    width: w,
    boxShadow: `0 0 0 1px ${accent}22, 0 8px 24px rgba(0,0,0,0.4)`,
    overflow: 'visible',
    fontFamily: "'Inter', sans-serif",
    position: 'relative',
  }),
  header: {
    background: `linear-gradient(90deg, ${accent}22 0%, transparent 100%)`,
    borderBottom: `1px solid ${accent}33`,
    padding: '8px 12px',
    display: 'flex', alignItems: 'center', gap: '8px',
    borderRadius: '10px 10px 0 0',
  },
  dot: { width: 8, height: 8, borderRadius: '50%', background: accent },
  title: {
    fontSize: '11px', fontWeight: 600, letterSpacing: '0.08em',
    textTransform: 'uppercase', color: '#fbbf24',
    fontFamily: "'Space Mono', monospace",
  },
  body: { padding: '10px 12px' },
  label: { fontSize: '10px', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 },
  textarea: {
    background: '#0d1017',
    border: '1px solid #2a2f3d',
    borderRadius: '5px',
    padding: '6px 8px',
    color: '#e2e8f0',
    fontSize: '12px',
    width: '100%',
    resize: 'none',
    lineHeight: 1.6,
    outline: 'none',
    fontFamily: "'Inter', sans-serif",
    overflow: 'hidden',
    display: 'block',
  },
  varTag: (i, total) => ({
    fontSize: '9px',
    color: '#94a3b8',
    position: 'absolute',
    left: 2,
    top: `${(100 / (total + 1)) * (i + 1)}%`,
    transform: 'translateY(-50%)',
    pointerEvents: 'none',
    whiteSpace: 'nowrap',
    background: '#13161e',
    padding: '1px 3px',
    borderRadius: 3,
  }),
};

export const TextNode = ({ id, data }) => {
  const [text, setText] = useState(data?.text || '{{input}}');
  const taRef = useRef(null);
  const [taSize, setTaSize] = useState({ w: MIN_W - 24, h: MIN_H - 52 });

  const vars = extractVars(text);

  useEffect(() => {
    if (!taRef.current) return;
    taRef.current.style.height = 'auto';
    const sh = Math.max(taRef.current.scrollHeight, 60);
    const sw = Math.max(taRef.current.scrollWidth, MIN_W - 24);
    taRef.current.style.height = sh + 'px';
    setTaSize({ w: sw, h: sh });
  }, [text]);

  const nodeW = Math.max(MIN_W, taSize.w + 24);

  return (
    <div style={styles.node(nodeW)}>
      {/* Variable handles */}
      {vars.map((v, i) => (
        <Handle
          key={v}
          type="target"
          position={Position.Left}
          id={`${id}-var-${v}`}
          style={{ top: `${(100 / (vars.length + 1)) * (i + 1)}%` }}
          title={v}
        />
      ))}
      {/* Variable labels */}
      <div style={{ position: 'absolute', left: 0, top: 0, width: '100%', height: '100%', pointerEvents: 'none' }}>
        {vars.map((v, i) => (
          <span key={v} style={styles.varTag(i, vars.length)}>{v}</span>
        ))}
      </div>

      <div style={styles.header}>
        <span style={styles.dot} />
        <span style={styles.title}>Text</span>
      </div>
      <div style={styles.body}>
        <div style={styles.label}>Content</div>
        <textarea
          ref={taRef}
          value={text}
          onChange={e => setText(e.target.value)}
          style={{ ...styles.textarea, height: taSize.h }}
          placeholder="Type text or use {{variable}}"
          onFocus={e => e.target.style.borderColor = accent}
          onBlur={e => e.target.style.borderColor = '#2a2f3d'}
        />
      </div>
      <Handle
        type="source"
        position={Position.Right}
        id={`${id}-output`}
        style={{ top: '50%' }}
      />
    </div>
  );
};
